contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint setupAmount, uint playAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (setupAmount) + (playAmount)); require(setupAmount <= 1000000000000000000000000000000); require(playAmount <= 1000000000000000000000000000000);
        require(setupAmount == 10);
        require(playAmount == 10);
        require(address(this).balance >= setupAmount + playAmount);

        bool setupReverted;
        c.play{value: setupAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setupReverted = true; } else { setupReverted = false; }
        require(!setupReverted);

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool playReverted;
        c.play{value: playAmount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { playReverted = true; } else { playReverted = false; }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(playReverted || potAfter == 0 || potAfter == potBefore + playAmount);
    }

    receive() external payable {}
}

