// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 setupAmount, uint256 playAmount) internal {
        setupAmount = bound(setupAmount, 0, 1000000000000000000000000000000);
        playAmount = bound(playAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        setupAmount = 10;
        playAmount = 10;
        vm.assume(address(this).balance >= setupAmount + playAmount);
        bool setupReverted;
        try c.play{value: setupAmount}() { setupReverted = false; } catch { setupReverted = true; }
        vm.assume(!setupReverted);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        bool playReverted;
        try c.play{value: playAmount}() { playReverted = false; } catch { playReverted = true; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(playReverted || potAfter == 0 || potAfter == potBefore + playAmount);
    }

    function testFuzz_run(uint256 setupAmount, uint256 playAmount) public {
        _run(setupAmount, playAmount);
    }

    receive() external payable {}
}
